from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

CENT = Decimal("0.01")
FOUR_DP = Decimal("0.0001")
BRACKETS = [
    (Decimal("0"), Decimal("12450"), 19),
    (Decimal("12450"), Decimal("20200"), 24),
    (Decimal("20200"), Decimal("35200"), 30),
    (Decimal("35200"), Decimal("60000"), 37),
    (Decimal("60000"), Decimal("300000"), 45),
    (Decimal("300000"), None, 47),
]


def _needed_prec(value, target_exp):
    try:
        adj = value.adjusted()
    except Exception:
        adj = 0
    return max(28, adj - target_exp + 1 + 20)


def _quantize_in_ctx(value, quantum, rounding=ROUND_HALF_UP):
    return value.quantize(quantum, rounding=rounding)


def _parse_income(income):
    if not isinstance(income, str):
        raise ValueError("income must be a string")
    try:
        amount = Decimal(income)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid income: {income!r}") from None
    if not amount.is_finite():
        raise ValueError("income must be finite")
    if amount < 0:
        raise ValueError("income must be >= 0")
    exp = amount.as_tuple().exponent
    if isinstance(exp, int) and exp < -2:
        raise ValueError("income must have at most 2 decimal places")
    prec = _needed_prec(amount, -2)
    with localcontext() as ctx:
        ctx.prec = prec
        try:
            result = amount.quantize(CENT)
        except InvalidOperation:
            raise ValueError("income must have at most 2 decimal places") from None
    return result


def tax_breakdown(income):
    amount = _parse_income(income)
    prec = _needed_prec(amount, -2)
    with localcontext() as ctx:
        ctx.prec = prec
        ctx.rounding = ROUND_HALF_UP
        rows = []
        for lower, upper, rate in BRACKETS:
            if amount <= lower:
                continue
            top = amount if upper is None else min(amount, upper)
            taxable = _quantize_in_ctx(top - lower, CENT, ROUND_HALF_UP)
            if taxable <= 0:
                continue
            tax = _quantize_in_ctx(
                taxable * Decimal(rate) / Decimal(100), CENT, ROUND_HALF_UP
            )
            rows.append(
                {
                    "from": _quantize_in_ctx(lower, CENT),
                    "to": None if upper is None else _quantize_in_ctx(upper, CENT),
                    "rate_percent": rate,
                    "taxable": taxable,
                    "tax": tax,
                }
            )
        return rows


def income_tax(income):
    rows = tax_breakdown(income)
    if not rows:
        return Decimal("0.00")
    prec = max(_needed_prec(row["tax"], -2) for row in rows)
    with localcontext() as ctx:
        ctx.prec = prec
        ctx.rounding = ROUND_HALF_UP
        total = sum((row["tax"] for row in rows), Decimal("0.00"))
        return total.quantize(CENT, rounding=ROUND_HALF_UP)


def effective_rate_percent(income):
    amount = _parse_income(income)
    if amount == 0:
        return Decimal("0.0000")
    tax = income_tax(income)
    prec = max(_needed_prec(tax, -4), _needed_prec(amount, -4))
    with localcontext() as ctx:
        ctx.prec = prec
        ctx.rounding = ROUND_HALF_UP
        rate = (tax / amount * Decimal(100)).quantize(
            FOUR_DP, rounding=ROUND_HALF_UP
        )
        return rate
